class Solution {
  public long countDistinct(long n) {
    String s = Long.toString(n);
    int L = s.length();
    long[] pow9 = new long[L + 1];
    pow9[0] = 1;
    for (int i = 1; i <= L; i++) pow9[i] = pow9[i - 1] * 9;
    long total = 0;
    for (int len = 1; len < L; len++) total += pow9[len];
    boolean full = true;
    for (int i = 0; i < L; i++) {
      int d = s.charAt(i) - '0';
      total += (long) Math.max(0, d - 1) * pow9[L - 1 - i];
      if (d == 0) {
        full = false;
        break;
      }
    }
    return full ? total + 1 : total;
  }
}
